SELECT id, conversation_id, user_id, client_request_id, role, content, create_time
FROM chat_messages
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND client_request_id = #{clientRequestId}
  AND role = #{role}
ORDER BY id ASC
LIMIT 1

